
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_revscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_revscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884599759456280e+00, -4.785714894897703e+00, -4.647112364194049e+00, -4.455026318356187e+00, -4.193098167502218e+00, -3.844090094289395e+00, -3.394016512737321e+00, -2.839615189603265e+00, -2.198340209805520e+00, -1.505738863770397e+00, -8.505484586013627e-01, -6.135766201495559e-01, -6.289329851553630e-01, -5.332949574218515e-01, -3.636781144341429e-01, -1.966402995729193e-01, -7.813152702579954e-02, -2.080949954599957e-02, -2.911859748739815e-03, -1.386992057671685e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


